CREATE TYPE "OrderStatus" AS ENUM ('pending', 'confirmed', 'cancelled', 'dispatched', 'delivered');
CREATE TYPE "PaymentStatus" AS ENUM ('pending', 'authorized', 'failed', 'refunded');
CREATE TYPE "OutboxStatus" AS ENUM ('pending', 'published', 'failed');
CREATE TABLE "orders" ("id" UUID NOT NULL, "buyerId" UUID NOT NULL, "status" "OrderStatus" NOT NULL DEFAULT 'pending', "totalAmount" DECIMAL(12,2) NOT NULL, "currency" VARCHAR(3) NOT NULL DEFAULT 'COP', "deliveryAddress" VARCHAR(500) NOT NULL, "paymentStatus" "PaymentStatus" NOT NULL DEFAULT 'pending', "idempotencyKey" VARCHAR(180), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "orders_pkey" PRIMARY KEY ("id"));
CREATE TABLE "order_items" ("id" UUID NOT NULL, "orderId" UUID NOT NULL, "productId" UUID NOT NULL, "quantity" DECIMAL(12,3) NOT NULL, "unitPrice" DECIMAL(12,2) NOT NULL, "subtotal" DECIMAL(12,2) NOT NULL, "priceVersionId" UUID, "productName" VARCHAR(180), "reservationId" UUID, CONSTRAINT "order_items_pkey" PRIMARY KEY ("id"));
CREATE TABLE "carts" ("id" UUID NOT NULL, "buyerId" UUID NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "carts_pkey" PRIMARY KEY ("id"));
CREATE TABLE "cart_items" ("id" UUID NOT NULL, "cartId" UUID NOT NULL, "productId" UUID NOT NULL, "quantity" DECIMAL(12,3) NOT NULL, "unitPrice" DECIMAL(12,2), "priceVersionId" UUID, CONSTRAINT "cart_items_pkey" PRIMARY KEY ("id"));
CREATE TABLE "order_outbox_events" ("id" UUID NOT NULL, "eventType" VARCHAR(120) NOT NULL, "aggregateId" UUID NOT NULL, "payload" JSONB NOT NULL, "status" "OutboxStatus" NOT NULL DEFAULT 'pending', "attempts" INTEGER NOT NULL DEFAULT 0, "availableAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "publishedAt" TIMESTAMP(3), CONSTRAINT "order_outbox_events_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "orders_idempotencyKey_key" ON "orders"("idempotencyKey"); CREATE INDEX "orders_buyerId_createdAt_idx" ON "orders"("buyerId", "createdAt"); CREATE INDEX "order_items_productId_idx" ON "order_items"("productId"); CREATE UNIQUE INDEX "carts_buyerId_key" ON "carts"("buyerId"); CREATE UNIQUE INDEX "cart_items_cartId_productId_key" ON "cart_items"("cartId", "productId"); CREATE INDEX "order_outbox_events_status_availableAt_idx" ON "order_outbox_events"("status", "availableAt");
ALTER TABLE "order_items" ADD CONSTRAINT "order_items_orderId_fkey" FOREIGN KEY ("orderId") REFERENCES "orders"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "cart_items" ADD CONSTRAINT "cart_items_cartId_fkey" FOREIGN KEY ("cartId") REFERENCES "carts"("id") ON DELETE CASCADE ON UPDATE CASCADE;
